/** 地面横向位移 dx（px）→ 车轮转角（度）。滚动方向与画面前进方向一致 */
export const sideWheelDeg = (dx: number, r: number = ES9_SIDE_WHEEL_R) =>
  ((dx / r) * 57.2957795) % 360;
